const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)],esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),rm=n=>'RM '+(n/100).toFixed(2),uid=()=>crypto.randomUUID();
const KEY='kongsipay-demo-v1';let view='overview',filter='all';
function seed(){const s={group:'Geng Rumah',members:[{id:'ali',name:'Ali'},{id:'sara',name:'Sara'},{id:'amir',name:'Amir'},{id:'nina',name:'Nina'},{id:'danial',name:'Danial'}],subscriptions:[{id:'video',name:'YouTube Family',price:6000,members:['ali','sara','amir','nina','danial'],payer:'ali',due:'2026-10-25',frequency:'Bulanan',mode:'Owner advance',providerPaid:true,color:'#512b2d',ink:'#ff9b9b',symbol:'▶'},{id:'music',name:'Spotify Family',price:4000,members:['ali','sara','amir','nina'],payer:'sara',due:'2026-10-18',frequency:'Bulanan',mode:'Prepaid',providerPaid:false,color:'#24462f',ink:'#7be6a1',symbol:'≋'},{id:'cloud',name:'Cloud Storage',price:1800,members:['ali','sara','nina'],payer:'ali',due:'2026-10-28',frequency:'Bulanan',mode:'Prepaid',providerPaid:false,color:'#293d54',ink:'#94c5fd',symbol:'☁'}],charges:[],payments:[],activity:[]};for(const sub of s.subscriptions)Ledger.cycle(s,sub,'2026-10',sub.due);const old={id:uid(),subscription:'video',member:'amir',payee:'ali',amount:1200,period:'2026-09',due:'2026-09-25',self:false};s.charges.unshift(old);const pay=(sub,m,amount,status)=>{const c=s.charges.find(x=>x.subscription===sub&&x.member===m&&x.period==='2026-10');s.payments.push({id:uid(),charge:c.id,amount,method:'Bank transfer',reference:'DEMO-'+m,status,date:'2026-10-07T10:00:00Z'});};pay('video','sara',1200,'approved');pay('video','nina',1200,'approved');pay('video','danial',600,'approved');pay('music','ali',1000,'approved');pay('cloud','sara',600,'pending');return s;}
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(!state||!Array.isArray(state.charges)||!Array.isArray(state.members)||!Array.isArray(state.payments))state=seed();}catch{state=seed();}
const member=id=>state.members.find(m=>m.id===id)?.name||'Ahli',subName=id=>state.subscriptions.find(s=>s.id===id)?.name||'Subscription',nameView={overview:'Ringkasan',subscriptions:'Subscription',payments:'Bayaran & hutang',members:'Ahli kumpulan'};
const charges=()=>state.charges.filter(c=>!c.self),sum=(a,f)=>a.reduce((n,x)=>n+f(x),0),today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kuala_Lumpur',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('ms-MY',{day:'numeric',month:'short'});
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500);}
function save(message){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Storan browser penuh. Perubahan ini hanya kekal sehingga halaman ditutup.');render();return;}render();if(message)toast(message);}
function log(text){state.activity.unshift({text,date:new Date().toISOString()});}
function status(c){if(!Ledger.balance(state,c))return '<span class="badge">Dah bayar</span>';if(Ledger.pending(state,c.id))return '<span class="badge wait">Dalam semakan</span>';if(Ledger.paid(state,c.id))return '<span class="badge wait">Bayar sebahagian</span>';return c.due<today()?'<span class="badge debt">Tertunggak</span>':'<span class="badge neutral">Belum bayar</span>';}
function icon(s){return `<span class="service-icon" style="background:${s.color};color:${s.ink}">${esc(s.symbol)}</span>`;}
function heading(title,subtitle,action=''){return `<div class="title-row"><div><h1>${title}</h1><p class="lead">${subtitle}</p></div>${action}</div>`;}
function metrics(){const cs=charges(),total=sum(cs,c=>c.amount),received=sum(cs,c=>Ledger.paid(state,c.id)),pending=sum(cs,c=>Ledger.pending(state,c.id)),debt=sum(cs.filter(c=>c.due<today()),c=>Ledger.balance(state,c));return `<div class="metrics"><div class="metric feature"><label>Baki kutipan ahli</label><strong>${rm(total-received)}</strong><small>Termasuk bayaran dalam semakan</small></div><div class="metric"><label>Dah diterima</label><strong>${rm(received)}</strong><small>Bayaran yang telah disahkan</small></div><div class="metric"><label>Menunggu semakan</label><strong>${rm(pending)}</strong><small>${state.payments.filter(p=>p.status==='pending').length} bayaran perlu disahkan</small></div><div class="metric"><label>Hutang tertunggak</label><strong>${rm(debt)}</strong><small>Baki selepas tarikh akhir</small></div></div>`;}
function chargeTable(cs){return `<div class="table-wrap"><table><thead><tr><th>Ahli / penerima</th><th>Subscription</th><th>Tarikh akhir</th><th>Baki</th><th>Status</th><th>Tindakan</th></tr></thead><tbody>${cs.length?cs.map(c=>`<tr><td>${esc(member(c.member))}<small>Kepada ${esc(member(c.payee))}</small></td><td>${esc(subName(c.subscription))}<small>${esc(c.period)}</small></td><td>${dateLabel(c.due)}</td><td>${rm(Ledger.balance(state,c))}<small>Daripada ${rm(c.amount)}</small></td><td>${status(c)}</td><td>${Ledger.available(state,c)>0?`<button class="table-btn" data-pay="${c.id}">Rekod bayar</button>`:'<span class="muted">—</span>'}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">Tiada caj dalam kategori ini.</td></tr>'}</tbody></table></div>`;}
function overview(){const cs=charges(),total=sum(cs,c=>c.amount),received=sum(cs,c=>Ledger.paid(state,c.id)),percent=total?Math.round(received/total*100):0;return heading('Duit kongsi, semua jelas.','Hai Ali. Ini ringkasan kutipan untuk '+esc(state.group)+'.','<button class="primary" data-add-sub>＋ Tambah subscription</button>')+metrics()+`<div class="grid"><div><div class="panel"><div class="panel-head"><h2>Subscription aktif <span class="muted">${state.subscriptions.length}</span></h2><button class="text-btn" data-nav="subscriptions">Lihat semua</button></div>${state.subscriptions.map(s=>`<div class="subrow">${icon(s)}<div class="subinfo"><h3>${esc(s.name)}</h3><small>${s.members.length} ahli · ${esc(s.frequency)} · Due ${dateLabel(s.due)}</small></div><div class="money"><strong>${rm(s.price)}</strong><small>${esc(s.mode)}</small></div></div>`).join('')}</div><div class="note-box"><span style="font-size:24px">◷</span><p><strong>Bil provider ≠ kutipan ahli.</strong><br>Bil yang dah dibayar owner masih boleh ada baki hutang member.</p></div></div><div><div class="panel"><div class="panel-head"><h2>Progress kutipan</h2><span class="badge">${percent}%</span></div><div class="collection"><div class="total">${rm(received)} <small>/ ${rm(total)}</small></div><div class="progress"><i style="width:${percent}%"></i></div><div class="split"><span>Semua caj, termasuk baki lama</span><span>Disahkan</span></div></div>${state.members.slice(0,3).map(m=>`<div class="member-row"><span class="avatar small">${esc(m.name[0])}</span><div class="subinfo">${esc(m.name)}<br><small>Baki perlu bayar</small></div><strong style="font-size:14px">${rm(sum(cs.filter(c=>c.member===m.id),c=>Ledger.balance(state,c)))}</strong></div>`).join('')}</div></div></div><div class="panel"><div class="panel-head"><h2>Perlu perhatian</h2><button class="text-btn" data-nav="payments">Semua bayaran</button></div>${chargeTable(cs.filter(c=>Ledger.balance(state,c)>0).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,5))}</div>`;}
function subscriptions(){return heading('Subscription','Urus plan, pembayar dan caj setiap kitaran.','<button class="primary" data-add-sub>＋ Tambah subscription</button>')+`<div class="subcards">${state.subscriptions.map(s=>`<article class="subcard">${icon(s)}<h2>${esc(s.name)}</h2><p class="lead">${s.members.length} ahli berkongsi</p><div class="price">${rm(s.price)} <small>/ ${s.frequency==='Tahunan'?'tahun':'bulan'}</small></div><dl><div><dt>Pembayar provider</dt><dd>${esc(member(s.payer))}</dd></div><div><dt>Renewal</dt><dd>${dateLabel(s.due)}</dd></div><div><dt>Mode kutipan</dt><dd>${esc(s.mode)}</dd></div><div><dt>Bil provider</dt><dd><span class="badge ${s.providerPaid?'':'wait'}">${s.providerPaid?'Dah dibayar':'Belum dibayar'}</span></dd></div></dl><button class="secondary" data-provider="${s.id}">${s.providerPaid?'Lihat rekod bil':'Tandakan bil dibayar'}</button><button class="text-btn" data-cycle="${s.id}">Jana caj kitaran lain</button></article>`).join('')}</div><p class="help">Harga demo ialah rekaan. Setiap caj menyimpan penerima dan jumlah asalnya. Caj baharu dijana secara manual dalam prototaip ini.</p>`;}
function payments(){let cs=charges();if(filter==='debt')cs=cs.filter(c=>c.due<today()&&Ledger.balance(state,c)>0);if(filter==='unpaid')cs=cs.filter(c=>Ledger.balance(state,c)>0);if(filter==='paid')cs=cs.filter(c=>!Ledger.balance(state,c));const pending=state.payments.filter(p=>p.status==='pending');return heading('Bayaran & hutang','Bayaran separa, baki lama dan pengesahan dalam satu tempat.','<button class="secondary" id="export">Export CSV</button>')+metrics()+(pending.length?`<div class="panel"><div class="panel-head"><h2>Menunggu pengesahan</h2><span class="badge wait">${pending.length} bayaran</span></div>${pending.map(p=>{const c=state.charges.find(c=>c.id===p.charge);return `<div class="subrow"><span class="avatar small">${esc(member(c.member)[0])}</span><div class="subinfo"><h3>${esc(member(c.member))} · ${rm(p.amount)}</h3><small>${esc(subName(c.subscription))} · Kepada ${esc(member(c.payee))}<br>${esc(p.method)} · Ref: ${esc(p.reference||'Tiada')}</small></div><div class="actions"><button class="table-btn" data-approve="${p.id}">Sahkan</button><button class="text-btn" data-reject="${p.id}">Tolak</button></div></div>`;}).join('')}</div>`:'')+`<div class="filters">${[['all','Semua caj'],['unpaid','Ada baki'],['debt','Tertunggak'],['paid','Dah bayar']].map(([k,v])=>`<button class="filter ${filter===k?'active':''}" data-filter="${k}">${v}</button>`).join('')}</div><div class="panel">${chargeTable(cs)}</div><div class="panel"><div class="panel-head"><h2>Aktiviti terkini</h2></div>${state.activity.length?state.activity.slice(0,8).map(a=>`<div class="subrow"><div class="subinfo">${esc(a.text)}<br><small>${new Date(a.date).toLocaleString('ms-MY')}</small></div></div>`).join(''):'<p class="empty">Aktiviti baharu akan direkodkan di sini.</p>'}</div>`;}
function members(){return heading('Ahli kumpulan','Rekod ahli dalam '+esc(state.group)+'.','<button class="primary" id="add-member">＋ Tambah ahli</button>')+`<div class="note-box"><p>Ini rekod ahli untuk demo. Jemputan, login dan perkongsian data antara peranti belum diaktifkan.</p></div><div class="membercards">${state.members.map(m=>`<article class="membercard"><span class="avatar">${esc(m.name[0])}</span><h2>${esc(m.name)}</h2><p>${state.subscriptions.filter(s=>s.members.includes(m.id)).length} subscription disertai<br>Baki perlu dibayar</p><strong>${rm(sum(charges().filter(c=>c.member===m.id),c=>Ledger.balance(state,c)))}</strong><p style="margin:18px 0 0">Perlu diterima: ${rm(sum(charges().filter(c=>c.payee===m.id),c=>Ledger.balance(state,c)))}</p></article>`).join('')}</div>`;}
function render(){const groupBtn=$('#group');groupBtn.textContent=state.group+' ⌄';$('#crumb').textContent='Workspace / '+nameView[view];$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#content').innerHTML=({overview,subscriptions,payments,members}[view])();bind();}
function navigate(v){if(!nameView[v])throw Error('Paparan tidak sah.');view=v;render();}
function modal(title,html,submit){$('#modal-title').textContent=title;$('#fields').innerHTML=html;$('#error').textContent='';$('#form').onsubmit=e=>{e.preventDefault();try{submit(new FormData(e.target));$('#modal').close();}catch(err){$('#error').textContent=err.message;}};$('#modal').showModal();}
const options=(selected)=>state.members.map(m=>`<option value="${m.id}" ${m.id===selected?'selected':''}>${esc(m.name)}</option>`).join('');
function addSub(){modal('Tambah subscription',`<label for="name">Nama subscription</label><input id="name" name="name" required maxlength="60" placeholder="Contoh: Family Video"><label for="price">Harga setiap kitaran (RM)</label><input id="price" name="price" type="number" min="0.01" max="1000000" step="0.01" required><label for="frequency">Kitaran</label><select id="frequency" name="frequency"><option>Bulanan</option><option>Tahunan</option></select><label for="due">Tarikh akhir kitaran pertama</label><input id="due" name="due" type="date" value="2026-10-25" required><label for="payer">Pembayar kepada provider</label><select id="payer" name="payer">${options('ali')}</select><label for="mode">Mode kutipan</label><select id="mode" name="mode"><option>Owner advance</option><option>Prepaid</option></select><label>Ahli — bahagi sama rata</label><div class="checks">${state.members.map(m=>`<label><input type="checkbox" name="members" value="${m.id}" checked>${esc(m.name)}</label>`).join('')}</div><p class="help">Baki sen diagihkan mengikut urutan ahli. Bahagian pembayar sendiri dikecualikan daripada kutipan.</p>`,f=>{const name=String(f.get('name')).trim(),members=f.getAll('members'),due=String(f.get('due'));if(!name||!members.length)throw Error('Isi nama dan pilih sekurang-kurangnya seorang ahli.');const price=Ledger.moneyInput(f.get('price'));if(price<members.length)throw Error('Jumlah terlalu kecil untuk bilangan ahli ini.');const sub={id:uid(),name,price,members,payer:f.get('payer'),due,frequency:f.get('frequency'),mode:f.get('mode'),providerPaid:false,color:'#334330',ink:'#c7fa72',symbol:name[0].toUpperCase()};Ledger.cycle(state,sub,due.slice(0,7),due);state.subscriptions.push(sub);log('Subscription '+name+' ditambah dan caj pertama dijana.');save('Subscription ditambah.');});}
function pay(id){const c=state.charges.find(c=>c.id===id);modal('Rekod bayaran',`<p class="help">${esc(member(c.member))} membayar ${esc(member(c.payee))}<br>${esc(subName(c.subscription))} · ${esc(c.period)}</p><label for="amount">Jumlah (RM) — maks. ${rm(Ledger.available(state,c))}</label><input id="amount" name="amount" type="number" min="0.01" step="0.01" max="${Ledger.available(state,c)/100}" value="${(Ledger.available(state,c)/100).toFixed(2)}" required><label for="method">Kaedah bayaran</label><select id="method" name="method"><option>Bank transfer</option><option>DuitNow</option><option>E-wallet</option><option>Cash</option></select><label for="reference">Reference / nota</label><input id="reference" name="reference" maxlength="160" placeholder="Contoh: BAYAR-OKT-001"><p class="help">Ini rekod demo sahaja. Tiada wang dipindahkan. Baki dikurangkan selepas bayaran disahkan.</p>`,f=>{Ledger.record(state,{charge:id,amount:Ledger.moneyInput(f.get('amount')),method:f.get('method'),reference:f.get('reference')});log('Bayaran '+member(c.member)+' dihantar untuk semakan.');save('Bayaran menunggu pengesahan.');});}
function bind(){$$('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));$$('[data-add-sub]').forEach(b=>b.onclick=addSub);$$('[data-pay]').forEach(b=>b.onclick=()=>pay(b.dataset.pay));$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});$$('[data-approve]').forEach(b=>b.onclick=()=>{try{const p=Ledger.approve(state,b.dataset.approve);log('Bayaran '+rm(p.amount)+' disahkan.');save('Bayaran disahkan. Baki dikemas kini.');}catch(e){toast(e.message);}});$$('[data-reject]').forEach(b=>b.onclick=()=>modal('Tolak bayaran','<label for="reason">Sebab</label><input name="reason" id="reason" required maxlength="160">',f=>{const reason=String(f.get('reason')).trim();if(!reason)throw Error('Masukkan sebab penolakan.');const p=state.payments.find(p=>p.id===b.dataset.reject);if(p.status!=='pending')throw Error('Bayaran sudah diproses.');p.status='rejected';p.reason=reason;log('Bayaran '+rm(p.amount)+' ditolak: '+reason);save('Bayaran ditolak.');}));$$('[data-provider]').forEach(b=>b.onclick=()=>{const s=state.subscriptions.find(s=>s.id===b.dataset.provider);if(s.providerPaid){toast('Bil '+s.name+' telah direkod sebagai dibayar oleh '+member(s.payer)+'.');return;}modal('Sahkan bil provider',`<p class="help">Rekod ${esc(member(s.payer))} telah membayar ${rm(s.price)} untuk ${esc(s.name)} pada kitaran ${esc(s.due.slice(0,7))}. Baki hutang ahli tidak berubah.</p>`,()=>{s.providerPaid=true;log(member(s.payer)+' membayar bil provider '+s.name+' ('+rm(s.price)+').');save('Bil provider ditandakan dibayar.');});});$$('[data-cycle]').forEach(b=>b.onclick=()=>{const s=state.subscriptions.find(s=>s.id===b.dataset.cycle);modal('Jana caj kitaran',`<label for="due">Tarikh akhir kitaran baharu</label><input name="due" id="due" type="date" required><p class="help">Satu caj setiap ahli akan dijana berdasarkan harga semasa ${rm(s.price)}. Kitaran yang sama tidak boleh dijana dua kali. Hutang lama kekal.</p>`,f=>{const due=String(f.get('due'));if(due<=s.due)throw Error('Pilih tarikh selepas kitaran semasa.');Ledger.cycle(state,s,due.slice(0,7),due);s.due=due;s.providerPaid=false;log('Caj '+s.name+' untuk '+due.slice(0,7)+' dijana.');save('Caj kitaran baharu dijana.');});});if($('#add-member'))$('#add-member').onclick=()=>modal('Tambah ahli demo','<label for="member-name">Nama ahli</label><input name="name" id="member-name" maxlength="40" required>',f=>{const name=String(f.get('name')).trim();if(!name)throw Error('Isi nama ahli.');if(state.members.some(m=>m.name.toLowerCase()===name.toLowerCase()))throw Error('Nama ahli sudah wujud.');state.members.push({id:uid(),name});log('Ahli '+name+' ditambah.');save('Ahli ditambah.');});if($('#export'))$('#export').onclick=exportCSV;}
function exportCSV(){const rows=[['Ahli','Penerima','Subscription','Kitaran','Jumlah RM','Disahkan RM','Baki RM'],...charges().map(c=>[member(c.member),member(c.payee),subName(c.subscription),c.period,(c.amount/100).toFixed(2),(Ledger.paid(state,c.id)/100).toFixed(2),(Ledger.balance(state,c)/100).toFixed(2)])];const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='kongsipay-penyata-demo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$$('nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('#close').onclick=$('#cancel').onclick=()=>$('#modal').close();$('#group').onclick=()=>modal('Nama kumpulan','<label for="group-name">Nama kumpulan demo</label><input name="name" id="group-name" maxlength="45" value="'+esc(state.group)+'" required>',f=>{const name=String(f.get('name')).trim();if(!name)throw Error('Isi nama kumpulan.');state.group=name;save('Nama kumpulan dikemas kini.');});
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_payment_summary',description:'Read totals from this device-local KongsiPay demo. Does not transfer money.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('No input fields accepted.');const cs=charges();return {group:state.group,currency:'MYR',outstandingCents:sum(cs,c=>Ledger.balance(state,c)),pendingCents:sum(cs,c=>Ledger.pending(state,c.id)),demo:true};}})).catch(()=>{});}catch{}}
